     requires
         phys_view().initialized,
         phys_view().inv(),
         frame.inv(),
     ensures
         phys_view().inv(),
         phys_view().initialized,
         // On success the frame remains allocated (it has gained a reference). The
         // increment itself is not stated: `phys_view()` is a single fixed value
