                 &&& phys_view().frames.allocated_frames.contains(frame@)
                 &&& phys_view().frames.refcounts.contains_key(frame@)
             },
             Err(_) => true,
         },
 )]
 pub(super) fn share(frame: FrameAddress) -> Result<(), Error> {
